import React, { useMemo } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  random,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
// No fonts needed for abstract shapes, but following protocol:
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};



export type SplashAnimationProps = Record<string, any>;

// --- Constants ---
const BEAM_COLORS = [
  "#ff1500", "#ffff00", "#ff00ff", "#00ff9f",
  "#ff5500", "#ffaa00", "#00a9ff", "#bf00ff",
  "#ffdd00", "#00ffff", "#ff153b", "#ff00cc"
];

const NUM_STRIPS = 20;
const NUM_BEAMS = 28;

// --- Sub-Components ---

const GradientStrips: React.FC<{
  delay: number;
  width: number;
  height: number;
  primaryColor: string;
}> = ({ delay, width, height, primaryColor }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Generate static data for strips based on seed "strips"
  const strips = useMemo(() => {
    return new Array(NUM_STRIPS).fill(true).map((_, i) => {
      const seed = `strip-${i}`;
      const stripWidthPercent = 100 / NUM_STRIPS;
      const left = i * stripWidthPercent;
      const w = stripWidthPercent + 0.5; // overlap slightly

      const fillPercentage = 10 + random(seed + "fill") * 40;
      const fadePoint = 60 + random(seed + "fade") * 40;
      const colorIndex = Math.floor(random(seed + "col") * BEAM_COLORS.length);
      const color = BEAM_COLORS[colorIndex];

      // Construct gradient similar to CSS
      const bg = `linear-gradient(to bottom, ${color} 0%, ${color} ${fillPercentage}%, rgba(0, 0, 0, 0) ${fadePoint}%, rgba(0, 0, 0, 0) 100%)`;

      return { left, width: w, bg };
    });
  }, []);

  // Animation: gradient-flow (translateY 0 -> -100%)
  const startFrame = delay * fps;
  const durationFrames = 2 * fps; // approx 2s duration

  const translateY = interpolate(
    frame,
    [startFrame, startFrame + durationFrames],
    [0, -100],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.linear,
    }
  );

  return (
    <div
      style={{
        position: "absolute",
        width: "100%",
        height: "300%", // As per .gradient-effect height: 300%
        top: 0,
        overflow: "hidden",
        transform: `translateY(${translateY}%)`,
      }}
    >
      {/* Glow before pseudo-element */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "70%", // As per .gradient-effect::before
          backgroundColor: primaryColor,
          boxShadow: `0px 0px 35px 28px ${primaryColor}`,
        }}
      />
      {/* Strips */}
      {strips.map((s, i) => (
        <div
          key={i}
          style={{
            position: "absolute",
            bottom: 0,
            height: "40%", // As per .segment-1 .gradient-effect [class*="strip-"]
            left: `${s.left}%`,
            width: `${s.width}%`,
            background: s.bg,
            zIndex: i,
          }}
        />
      ))}
    </div>
  );
};

const ColorBeams: React.FC<{ delay: number }> = ({ delay }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const startFrame = delay * fps;
  
  // Reveal opacity animation
  // 0% -> 40% -> 60% -> 100% (opacity 0 -> 0.3 -> 0.8 -> 1) over 2s
  const revealDuration = 2 * fps;
  const opacity = interpolate(
    frame,
    [
      startFrame,
      startFrame + revealDuration * 0.4,
      startFrame + revealDuration * 0.6,
      startFrame + revealDuration,
    ],
    [0, 0.3, 0.8, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  const beams = useMemo(() => {
    const b = new Array(NUM_BEAMS).fill(true).map((_, i) => {
      const seed = `beam-${i}`;
      const color = BEAM_COLORS[Math.floor(random(seed + "col") * BEAM_COLORS.length)];
      const width = (0.5 + random(seed + "width") * 2.5);
      // left mostly distributed 0-100 with some jitter
      const left = (i / NUM_BEAMS) * 100 + (random(seed + "pos") * 1.5 - 0.75);
      const delayOffset = random(seed + "delay") * 2; // 0-2s random delay
      const direction = i % 2 === 0 ? "left" : "right";
      const brightness = 1 + random(seed + "bright") * 0.8;

      return { color, width, left, delayOffset, direction, brightness };
    });
    return b.sort((a, b) => a.left - b.left);
  }, []);

  return (
    <div
      style={{
        position: "absolute",
        width: "100%",
        height: "100%",
        opacity,
      }}
    >
      {beams.map((beam, i) => {
        // Beam movement animation
        // Duration approx 5s
        const beamDuration = 5 * fps;
        const beamStart = startFrame + beam.delayOffset * fps;
        
        // Standardize movement progress 0 -> 1
        const t = interpolate(
            frame,
            [beamStart, beamStart + beamDuration],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        // Keyframes logic from CSS move-left/move-right
        // 0% -> 40% -> 50% -> 100%
        // We map t (0-1) to these keypoints
        
        let translateX = 0;
        let scaleX = 1;
        let beamOpacity = 0.8;

        if (beam.direction === "left") {
           // Left logic: 0->10->60->120 px
           if (t <= 0.4) {
             const subT = interpolate(t, [0, 0.4], [0, 1]);
             translateX = interpolate(subT, [0, 1], [0, 10]);
             beamOpacity = interpolate(subT, [0, 1], [0.8, 1]);
           } else if (t <= 0.5) {
             const subT = interpolate(t, [0.4, 0.5], [0, 1]);
             translateX = interpolate(subT, [0, 1], [10, 60]);
             beamOpacity = 1;
           } else {
             const subT = interpolate(t, [0.5, 1], [0, 1]);
             translateX = interpolate(subT, [0, 1], [60, 120]);
             scaleX = interpolate(subT, [0, 1], [1, 3]);
             beamOpacity = interpolate(subT, [0, 1], [1, 0.8]);
           }
        } else {
           // Right logic: 0->-10->-60->-120 px
           if (t <= 0.4) {
            const subT = interpolate(t, [0, 0.4], [0, 1]);
            translateX = interpolate(subT, [0, 1], [0, -10]);
            beamOpacity = interpolate(subT, [0, 1], [0.8, 1]);
          } else if (t <= 0.5) {
            const subT = interpolate(t, [0.4, 0.5], [0, 1]);
            translateX = interpolate(subT, [0, 1], [-10, -60]);
            beamOpacity = 1;
          } else {
            const subT = interpolate(t, [0.5, 1], [0, 1]);
            translateX = interpolate(subT, [0, 1], [-60, -120]);
            scaleX = interpolate(subT, [0, 1], [1, 3]);
            beamOpacity = interpolate(subT, [0, 1], [1, 0.8]);
          }
        }

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: `${beam.left}%`,
              width: `${beam.width}%`,
              height: "100%",
              backgroundColor: beam.color,
              boxShadow: `0px 0px 15px 2px ${beam.color}`,
              opacity: beamOpacity,
              filter: `brightness(${beam.brightness})`,
              transform: `translateX(${translateX}px) scaleX(${scaleX})`,
              willChange: "transform, opacity",
            }}
          />
        );
      })}
    </div>
  );
};

const SplashAnimation: React.FC<SplashAnimationProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryColor = "#ff0f1f",
  glowIntensity = 35,
}) => {
  useFontLoader([]); // No fonts needed, but strict pattern adherence

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const actualBgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- Main Scale Animation ---
  // CSS: animation: scale-up var(--animation-time) 0.5s ease-in forwards;
  // animation-time = 3.5s
  // delay 0.5s
  const scaleDuration = 3.5 * fps;
  const scaleDelay = 0.5 * fps;

  const scale = interpolate(
    frame,
    [scaleDelay, scaleDelay + scaleDuration],
    [1, 15],
    {
      easing: Easing.in(Easing.quad), // "ease-in" approx
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // --- Segment 1 Fade ---
  // CSS: animation: fade-segment 2s 0.6s forwards;
  // 0.6s delay, 2s duration
  const fadeSegStart = 0.6 * fps;
  const fadeSegDuration = 2 * fps;
  // CSS fades bg color from rgba(255, 15, 31, 0.5) to 0
  // We'll just interpolate opacity of the BG color
  const seg1BgOpacity = interpolate(
    frame,
    [fadeSegStart, fadeSegStart + fadeSegDuration],
    [0.5, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );
  const seg1BgColor = `rgba(255, 15, 31, ${seg1BgOpacity})`;


  // Container style
  const containerStyle: React.CSSProperties = {
    position: "relative",
    width: 300, // Keeping strict to original CSS scale logic
    height: 300,
    transform: `scale(${scale})`,
    transformOrigin: "30% center",
    backgroundSize: "4000px",
    backgroundPosition: "-1950px 0",
    overflow: "hidden",
  };

  // Center the 300x300 container in the current viewport
  // The original CSS has the container centered in a flex parent.
  // We can use AbsoluteFill and flex center.
  
  return (
    <AbsoluteFill
      style={{
        backgroundColor: actualBgColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div style={containerStyle}>
        
        {/* Background Circle (.splash-animation::before) */}
        <div
            style={{
                content: '""',
                position: "absolute",
                backgroundColor: actualBgColor, // Matches bg color to create mask effect
                width: "150%",
                height: "30%",
                left: "-25%",
                bottom: "-27%",
                borderRadius: "50%",
                zIndex: 5,
                transformOrigin: "left center",
            }}
        />

        {/* Segment 1 */}
        <div
          style={{
            position: "absolute",
            width: "19.5%",
            height: "100%",
            backgroundColor: seg1BgColor,
            left: "22.4%",
            top: 0,
            transform: "rotate(180deg)",
            overflow: "visible", // Original css didn't hide overflow here?
          }}
        >
            <GradientStrips
                delay={1.2}
                width={300}
                height={300}
                primaryColor={primaryColor}
            />
             <div style={{
                 position: "absolute",
                 width: "100%",
                 height: "100%",
                 zIndex: 10
             }}>
                <ColorBeams delay={1.6} />
             </div>
        </div>

        {/* Segment 2 */}
        <div
          style={{
            position: "absolute",
            width: "19.5%",
            height: "100%",
            left: "57.8%",
            top: 0,
            transform: "rotate(180deg)",
            overflow: "hidden",
          }}
        >
            <GradientStrips
                delay={0.5}
                width={300}
                height={300}
                primaryColor={primaryColor}
            />
        </div>

        {/* Segment 3 */}
        <div
          style={{
            position: "absolute",
            width: "19%",
            height: "150%",
            left: "40.5%",
            top: "-25%",
            transform: "rotate(-19.5deg)",
            boxShadow: "0px 0px 35px -12px rgba(0, 0, 0, 0.4)",
            overflow: "hidden",
          }}
        >
            <GradientStrips
                delay={0.8}
                width={300}
                height={300}
                primaryColor={primaryColor}
            />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SplashAnimation;